SELECT COUNT(*) AS total_printings
FROM cards
WHERE power > 3 AND power <= 10;

SELECT ROUND(100.0 * COUNT(CASE WHEN Diagnosis LIKE '%systemic lupus erythematosus%' OR Diagnosis LIKE '%SLE%' THEN 1 END) * 1.0 / COUNT(*), 2) AS percentage_sle_with_thrombosis
FROM Examination
WHERE Thrombosis = 1;

WITH chlorine_atoms AS (
  SELECT atom_id FROM atom WHERE element = 'cl'
), bonded_atoms AS (
  SELECT CASE WHEN c.atom_id IN (SELECT atom_id FROM chlorine_atoms) THEN c.atom_id2 ELSE c.atom_id END AS bonded_atom_id
  FROM connected c
  WHERE c.atom_id IN (SELECT atom_id FROM chlorine_atoms) OR c.atom_id2 IN (SELECT atom_id FROM chlorine_atoms)
)
SELECT COUNT(DISTINCT bonded_atom_id) AS count_bonded_to_chlorine
FROM bonded_atoms;
